/**
 * @name Command injection via subprocess/os.system
 * @description Using subprocess or os.system with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // System command execution via os.system, subprocess.call, etc.
    exists(DataFlow::CallCfgNode call |
      // os.system(command)
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // subprocess.call(command, ...)
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // os.popen(command)
      call = API::moduleImport("os").getMember("popen").getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name String formatting injection
 * @description Using string formatting with untrusted input can lead to injection attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/string-format-injection
 * @tags security
 *        external/cwe/cwe-134
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module StringFormatConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // String formatting operations
    exists(DataFlow::CallCfgNode call |
      // str.format() method
      call = API::moduleImport("builtins").getMember("str").getMember("format").getACall() and
      sink = call.getArg(0)  // The format string is the first argument to format()
    )
    or
    exists(DataFlow::CallCfgNode call |
      // % formatting operator
      call = API::moduleImport("builtins").getMember("str").getMember("__mod__").getACall() and
      sink = call.getArg(0)  // The format string is the first argument to __mod__()
    )
    or
    exists(DataFlow::CallCfgNode call |
      // f-string formatting (Python 3.6+)
      call = API::moduleImport("builtins").getMember("str").getMember("__format__").getACall() and
      sink = call.getArg(0)  // The format string is the first argument to __format__()
    )
  }
}

module StringFormatFlow = TaintTracking::Global<StringFormatConfig>;
import StringFormatFlow::PathGraph

from StringFormatFlow::PathNode source, StringFormatFlow::PathNode sink
where StringFormatFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "String formatting injection from $@.", source.getNode(), "user input"
